    if (!this._providerInstance) {
      this._providerInstance = createOpenAICompatible({
        name: "cliProxyApi",
        baseURL: config.ANTIGRAVITY_BASE_URL ?? "",
        headers: {
          Authorization: `Bearer ${config.ANTIGRAVITY_API_KEY ?? ""}`,
        },
        includeUsage: true,
      })
    }
    return this._providerInstance
  }

